305: /* Add the object 'obj' string representation to the client output buffer. */
306: void addReply(client *c, robj *obj) {
307:     if (prepareClientToWrite(c) != C_OK) return;
308: 
309:     if (sdsEncodedObject(obj)) {
310:         if (_addReplyToBuffer(c,obj->ptr,sdslen(obj->ptr)) != C_OK)
311:             _addReplyProtoToList(c,obj->ptr,sdslen(obj->ptr));
312:     } else if (obj->encoding == OBJ_ENCODING_INT) {
313:         /* For integer encoded strings we just convert it into a string
314:          * using our optimized function, and attach the resulting string
315:          * to the output buffer. */
316:         char buf[32];
317:         size_t len = ll2string(buf,sizeof(buf),(long)obj->ptr);
318:         if (_addReplyToBuffer(c,buf,len) != C_OK)
319:             _addReplyProtoToList(c,buf,len);
320:     } else {
321:         serverPanic("Wrong obj->encoding in addReply()");
322:     }
323: }
