325: /* Add the SDS 's' string to the client output buffer, as a side effect
326:  * the SDS string is freed. */
327: void addReplySds(client *c, sds s) {
328:     if (prepareClientToWrite(c) != C_OK) {
329:         /* The caller expects the sds to be free'd. */
330:         sdsfree(s);
331:         return;
332:     }
333:     if (_addReplyToBuffer(c,s,sdslen(s)) != C_OK)
334:         _addReplyProtoToList(c,s,sdslen(s));
335:     sdsfree(s);
336: }
