338: /* This low level function just adds whatever protocol you send it to the
339:  * client buffer, trying the static buffer initially, and using the string
340:  * of objects if not possible.
341:  *
342:  * It is efficient because does not create an SDS object nor an Redis object
343:  * if not needed. The object will only be created by calling
344:  * _addReplyProtoToList() if we fail to extend the existing tail object
345:  * in the list of objects. */
346: void addReplyProto(client *c, const char *s, size_t len) {
347:     if (prepareClientToWrite(c) != C_OK) return;
348:     if (_addReplyToBuffer(c,s,len) != C_OK)
349:         _addReplyProtoToList(c,s,len);
350: }"}

