352: /* Low level function called by the addReplyError...() functions.
353:  * It emits the protocol for a Redis error, in the form:
354:  *
355:  * -ERRORCODE Error Message<CR><LF>
356:  *
357:  * If the error code is already passed in the string 's', the error
358:  * code provided is used, otherwise the string "-ERR " for the generic
359:  * error code is automatically added. */
360: void addReplyErrorLength(client *c, const char *s, size_t len) {
361:     /* If the string already starts with "-..." then the error code
362:      * is provided by the caller. Otherwise we use "-ERR". */
363:     if (!len || s[0] != '-') addReplyProto(c,"-ERR ",5);
364:     addReplyProto(c,s,len);
365:     addReplyProto(c,"\r\n",2);
366: 
367:     /* Sometimes it could be normal that a slave replies to a master with
368:      * an error and this function gets called. Actually the error will never
369:      * be sent because addReply*() against master clients has no effect...
370:      * A notable example is:
371:      *
372:      *    EVAL 'redis.call("incr",KEYS[1]); redis.call("nonexisting")' 1 x
373:      *
374:      * Where the master must propagate the first change even if the second
375:      * will produce an error. However it is useful to log such events since
376:      * they are rare and may hint at errors in a script or a bug in Redis. */
377:     int ctype = getClientType(c);
378:     if (ctype == CLIENT_TYPE_MASTER || ctype == CLIENT_TYPE_SLAVE || c->id == CLIENT_ID_AOF) {
379:         char *to, *from;
380: 
381:         if (c->id == CLIENT_ID_AOF) {
382:             to = "AOF-loading-client";
383:             from = "server";
384:         } else if (ctype == CLIENT_TYPE_MASTER) {
385:             to = "master";
386:             from = "replica";
387:         } else {
388:             to = "replica";
389:             from = "master";
390:         }
391: 
392:         char *cmdname = c->lastcmd ? c->lastcmd->name : "<unknown>";
393:         serverLog(LL_WARNING,"== CRITICAL == This %s is sending an error "
394:                              "to its %s: '%s' after processing the command "
395:                              "'%s'", from, to, s, cmdname);
396:         server.stat_unexpected_error_replies++;
397:     }
398: }
