448:     if (!tail) return;
449: 
450:     /* We only try to trim the space is relatively high (more than a 1/4 of the
451:      * allocation), otherwise there's a high chance realloc will NOP.
452:      * Also, to avoid large memmove which happens as part of realloc, we only do
453:      * that if the used part is small.  */
454:     if (tail->size - tail->used > tail->size / 4 &&
455:         tail->used < PROTO_REPLY_CHUNK_BYTES)
456:     {
457:         c->reply_bytes -= tail->size;
458:         tail = zrealloc(tail, tail->used + sizeof(clientReplyBlock));
459:         /* take over the allocation's internal fragmentation (at least for
460:          * memory usage tracking) */
461:         tail->size = zmalloc_usable(tail) - sizeof(clientReplyBlock);
462:         c->reply_bytes += tail->size;
463:         listNodeValue(ln) = tail;
464:     }
465: }
466: 
467: /* Adds an empty object to the reply list that will contain the multi bulk
468:  * length, which is not known when this function is called. */
469: void *addReplyDeferredLen(client *c) {
470:     /* Note that we install the write event here even if the object is not
471:      * ready to be sent, since we are sure that before returning to the
472:      * event loop setDeferredAggregateLen() will be called. */
473:     if (prepareClientToWrite(c) != C_OK) return NULL;
474:     trimReplyUnusedTailSpace(c);
475:     listAddNodeTail(c->reply,NULL); /* NULL is our placeholder. */"}
